  async function loadConfig(kind) {
    const [path,title,example]=CONFIG[kind]; let data={items:[]}, warning='';
    try { data=await api(path); } catch(error) { warning=`<div class="callout warn">Live ${esc(title.toLowerCase())} could not be loaded: ${esc(error.message)}. Defaults are shown for reference; retry after controller storage recovers.</div>`; }
    const items=data.items||[];
    const lifecycle = doc => {
      const actions=[];
      if (['draft','rejected'].includes(doc.state)) actions.push(['submit','Submit for review']);
      if (doc.state === 'in_review') actions.push(['approve','Approve']);
      if (doc.state === 'approved') actions.push(['publish','Publish + auto-rollout']);
      return actions.map(([value,label])=>` <button class="secondary small" data-action="config-action" data-kind="${kind}" data-id="${esc(doc.id)}" data-value="${value}">${label}</button>`).join('');
    };
    renderPage(kind, `${warning}${panel(title,'Revisioned declarative assets stored in Supabase metadata. Drafts require independent review; publishing builds the canonical asset bundle and starts automatic fleet rollout.',table(['Name','ID','Revision','State','Updated','Configuration','Actions'],items.map(doc=>`<tr><td>${esc(doc.payload?.name||doc.id)}</td><td class="mono">${esc(doc.id)}</td><td>${doc.revision}</td><td>${badge(doc.state)}</td><td>${time(doc.updated_at)}</td><td><details><summary>View full content</summary><pre class="json-output">${esc(pretty(doc.payload?.config))}</pre></details></td><td><button class="secondary small" data-action="config-action" data-kind="${kind}" data-id="${esc(doc.id)}" data-value="edit">Edit draft</button> <button class="secondary small" data-action="config-action" data-kind="${kind}" data-id="${esc(doc.id)}" data-value="download">Download JSON</button> <button class="danger small" data-action="config-action" data-kind="${kind}" data-id="${esc(doc.id)}" data-value="delete">Delete</button>${lifecycle(doc)}</td></tr>`)))}${panel('Create or revise definition','Saving creates a draft revision in Supabase. It does not affect live parsing until independent approval and publication.',`<form id="config-form" data-kind="${kind}" class="form-grid"><label class="field">ID<input name="id" required title="Stable identifier for this asset. Reusing an ID creates a new revision."></label><label class="field">Name<input name="name" required></label><label class="field wide">Configuration JSON<textarea name="config" required>${esc(pretty(example))}</textarea><span class="hint">ⓘ Declarative JSON only. Validate the draft in Assurance, submit it, obtain independent approval, then publish to trigger verified fleet synchronization.</span></label><button class="primary" type="submit">Save draft revision</button></form>`)}`);
  }

