  async function loadUnknowns() {
    const results=await Promise.allSettled([api('/quarantine/summary'),api('/quarantine/records?limit=250'),api('/quarantine/history?limit=100')]);
    const summary=results[0].status==='fulfilled'?results[0].value:{}, records=results[1].status==='fulfilled'?(results[1].value.records||[]):[], history=results[2].status==='fulfilled'?(results[2].value.events||results[2].value.history||[]):[];
    const failures=results.map((result,index)=>result.status==='rejected'?`<div class="callout warn">${['Summary','Record queue','Reprocessing history'][index]} unavailable: ${esc(result.reason.message)}</div>`:'').join('');
    const reasons=new Map();records.forEach(item=>(item.error_codes||[item.error||'no_match']).forEach(code=>reasons.set(code,(reasons.get(code)||0)+1)));
    const diagnosis=reasons.size?[...reasons].sort((a,b)=>b[1]-a[1]).map(([code,count])=>`<tr><td><code>${esc(code)}</code></td><td>${count}</td><td>${code==='no_match'?'No eligible parser matched; inspect representative raw lines in Assurance.':code==='malformed_record'?'Input failed structural validation; confirm the source format and required fields.':'Review the exact source line and parser outcome in Assurance.'}</td></tr>`):[];
    const needsAttention=records.filter(item=>['dead_letter','manual_attention','replay_failed'].includes(item.status)||Number(item.attempt_count)>=5).length;
    renderPage('unknowns', `<div class="dashboard-intro"><div><p class="eyebrow">Runtime · retained source queue</p><h1>Quarantine and reprocessing</h1><p>Review unmatched records, preserve exact input, validate a parser in Assurance, then request a replay for its originating node.</p></div><div class="actions"><button class="secondary" data-action="quarantine-export" data-format="raw">Download raw lines</button><button class="secondary" data-action="quarantine-export" data-format="jsonl">Download quarantine JSONL</button><button class="secondary" data-action="navigate" data-page="parsers">Parser Catalog</button><button class="secondary" data-action="navigate" data-page="parser-sync">Parser Fleet Sync</button></div></div><div class="grid cols-4">${card('Waiting',number(summary.waiting??summary.quarantined??summary.total_pending),'Retained records awaiting parser review')}${card('Reprocessing',number(summary.reprocessing),'Replay accepted by controller')}${card('Resolved',number(summary.resolved??summary.reprocessed),'Successfully parsed after replay')}${card('Manual attention',number(needsAttention),'Replay failed or reached five attempts')}</div>${failures}${panel('Diagnosis by parser outcome','Common failure codes with a suggested next review step.',table(['Reason code','Records','Suggested review'],diagnosis,'No failure codes are currently reported.'))}${panel('Queue and exact source access','Record metadata is safe to list. Exact raw download is separately permission checked, audited, and available only when retention was enabled for that record.',table(['First seen','Client / service','Record','Attempts / parser','State / reason','Source / actions'],records.map(item=>`<tr><td>${time(item.first_seen||item.created_at)}</td><td><b>${esc(item.node_id||'—')}</b><br><small>${esc(item.service||'unknown service')}</small></td><td class="mono">${esc(item.id||item.record_id||'—')}<br><small>${esc((item.hash||item.sha256||'').slice(0,18))}</small></td><td>${number(item.attempt_count)} attempts<br><small>${esc(item.parser_revision||'no parser revision')}</small></td><td>${badge(Number(item.attempt_count)>=5?'manual_attention':item.status||'waiting')}<br><small>${esc((item.error_codes||[]).join(', ')||item.error||'No parser matched')}</small></td><td>${item.raw_available?`<button class="secondary small" data-action="quarantine-raw" data-id="${esc(item.id||item.record_id)}">Download exact raw</button> <button class="secondary small" data-action="quarantine-diagnose" data-id="${esc(item.id||item.record_id)}" data-service="${esc(item.service||'auto')}">Diagnose in Assurance</button>`:'Not retained'}</td></tr>`),'No quarantine records are currently available.'))}${panel('Retry records','Each replay is an explicit, auditable request. Repeated retries use bounded backoff and stop after five total attempts; dead-letter records require manual attention. Parser publishing and fleet retry proposals follow the separate approval workflow.',`<form id="quarantine-reprocess-form" class="form-grid"><label class="field">Record IDs<input name="record_ids" required placeholder="Paste one or more IDs, comma separated"></label><label class="field">Target client ID<input name="node_id" required placeholder="Originating node ID"></label><button class="primary" type="submit">Request replay</button><span class="hint wide">Parser changes are created or edited in Parser Catalog, validated in Assurance, then submitted for independent approval. Use Parser Fleet Sync to propose rollout to selected nodes; rollout approval remains required.</span></form>`)}${panel('Reprocessing history','Replay requests and client outcomes, including failed attempts and records still waiting for check-in.',table(['Time','Record','Client','Action','State','Details'],history.map(item=>`<tr><td>${time(item.timestamp||item.created_at)}</td><td class="mono">${esc(item.record_id||item.id||'—')}</td><td>${esc(item.node_id||'—')}</td><td>${esc(item.action||item.event||'reprocess')}</td><td>${badge(item.status||item.outcome||'pending')}</td><td>${esc(item.message||item.error||item.parser_revision||'—')}</td></tr>`)))}<div class="callout">Only records with explicit raw retention can be downloaded or replayed from the original source. Records that were never retained remain metadata-only; the UI cannot reconstruct their exact input. Replay attempts are capped at five and stop for manual attention.</div>`);
  }
  async function loadAPIMonitor() {
    const probes=['/health','/auth/me','/overview','/telemetry/stats','/telemetry/query?limit=1','/metrics/timeseries?window=1h','/fleet','/fleet/sync','/parser-sync','/metadata?limit=1','/parsers','/parser-packs','/assurance/cases','/assurance/parsers','/assurance/plans','/assurance/runs','/assurance/history','/quarantine/summary','/quarantine/records?limit=1','/quarantine/history?limit=1','/migration/reports','/artifacts','/rollouts','/rbac/roles','/users','/audit?limit=1','/system','/admin/ai-provider'];
    await Promise.allSettled(probes.map(path=>api(path)));
    const purposes={'/sync/snapshot':'Canonical NURSF state and freshness','/health':'Controller liveness','/auth/me':'Current authenticated operator and role','/overview':'Fleet, storage and operating summary','/telemetry/stats':'Ingest and processing counters','/telemetry/query':'Filtered processing records','/metrics/timeseries':'Aggregated processing and latency metrics','/fleet':'Registered nodes','/fleet/sync':'Registered clients, health and usage','/parser-sync':'Desired/applied parser revisions and drift','/metadata':'Bounded activity events','/parsers':'Built-in runtime parser inventory','/parser-packs':'Parser drafts, review and publication','/assurance/cases':'Retained validation fixtures','/assurance/parsers':'Assurance parser drafts','/assurance/plans':'Versioned Assurance test plans','/assurance/runs':'Persisted Assurance run evidence','/assurance/history':'Validation and parser review history','/quarantine/summary':'Waiting, replay and resolution counts','/quarantine/records':'Quarantine queue metadata','/quarantine/history':'Replay request and client outcomes','/migration/reports':'Parser source import reports','/artifacts':'Signed release artifacts','/rollouts':'Approval-gated actions and client delivery','/rbac/roles':'Role permission matrix','/users':'Operator accounts','/audit':'Immutable controller audit events','/system':'Controller version, resources and security','/admin/ai-provider':'Optional AI provider status'};
    const latest=new Map();state.apiHistory.forEach(item=>{if(!latest.has(`${item.method} ${item.path}`))latest.set(`${item.method} ${item.path}`,item);});
    const reachable=status=>status!=null&&(status<400||[401,403,405,422].includes(status));
    const latencies=[...latest.values()].map(item=>item.latency).sort((a,b)=>a-b),percentile=p=>latencies.length?latencies[Math.min(latencies.length-1,Math.ceil(p*latencies.length)-1)]:0,p50=percentile(.5),p95=percentile(.95);
    const rows=[...latest.values()].map(item=>`<tr><td>${badge(reachable(item.status)?'online':'offline')}</td><td><code>${esc(item.method)}</code></td><td class="mono">${esc(item.path)}</td><td>${esc(purposes[item.path]||'Authenticated controller API')}</td><td>${item.latency} ms</td><td>${item.status??'network error'}${item.error?`<br><small>${esc(item.error)}</small>`:''}</td><td>${time(item.at)}</td></tr>`);
    const ok=[...latest.values()].filter(item=>reachable(item.status)).length, failed=[...latest.values()].length-ok;
    renderPage('api-monitor',`<div class="dashboard-intro"><div><p class="eyebrow">Controller connectivity · authenticated probes</p><h1>API monitor</h1><p>Each status comes from an actual browser request. A 401/403 means the API is reachable and access was denied; network and server errors show as offline.</p></div><div class="actions"><button class="secondary" data-action="reload">Refresh probes</button></div></div><div class="grid cols-4">${card('Reachable APIs',number(ok),'Successful or permission-gated HTTP responses')}${card('Failed APIs',number(failed),'Network or server errors in latest calls')}${card('Latency p50',`${p50} ms`,'Latest response per route')}${card('Latency p95',`${p95} ms`,'Latest response per route')}</div>${panel('Current controller API status','Method, route, purpose, response latency and result for live API calls observed in this session.',table(['Status','Method','Path','Purpose','Latency','HTTP result','Last checked'],rows,'No API calls observed yet. Refresh probes to check controller connectivity.'))}${panel('Probe coverage','The monitor checks controller health, storage, telemetry, client sync, parser sync, metadata, Assurance history, parser catalog, rollouts and system status.','<p class="muted">The request history is held in this browser session and contains routes and status metadata only. Request bodies, credentials and log payloads are not recorded.</p>')}`);
  }

